   // reproduced 0/6 locally on this head AND on origin/main — pre-existing,
   // not PR-caused, fixed here at the test's own determinism level). A
   // rebuilt request re-asks for the same logical step and gets the same
   // answer, so steering and post-tool continuations converge instead of
   // skipping steps.
   final served = <String>{};
   AssistantMessageEventStream respondByState(
     Model model,
     Context context, {
     CancelToken? cancelToken,
   }) {
     final results = context.messages
         .whereType<ToolResultMessage>()
         .map((m) => m.toolCallId)
         .toSet();
     final List<AssistantMessageEvent> events;
