// Content-addressed responder, ONE tool round per turn: after each
// tool result the turn is ENDED with a distinctive marker text, so the
// next user input always starts a FRESH turn instead of being
// delivered as steering — the steering watchdog interrupts in-flight
// tools ("interrupting to deliver"), which is exactly what killed the
// scripted memory_add mid-run (its result came back "the run was
// interrupted before the tool finished" and mem2 stayed absent — CI
// run 43712787135; reproduced 0/6 locally on this head AND on
// origin/main, a pre-existing test-determinism gap, not a wrap
// regression). The continuation call after a tool is detected by the
// last context message being that tool's result; a fresh user turn is
// served with the next needed call by the tool results seen so far —
// a steering rebuild re-asks for the same step and gets the same
// answer, so the responder converges under any call pattern.
AssistantMessageEventStream respondByState(
  Model model,
  Context context, {
  CancelToken? cancelToken,
}) {
  final results = context.messages
      .whereType<ToolResultMessage>()
      .map((m) => m.toolCallId)
      .toSet();
  final last = context.messages.last;
  final List<AssistantMessageEvent> events;
  if (last is ToolResultMessage) {
    events = textTurn(
      last.toolCallId == 'c1'
          ? 'SET-DONE'
          : last.toolCallId == 'c2'
          ? 'CHECK-DONE'
          : 'ADD-DONE',
    );
  } else if (!results.contains('c1')) {
    events = toolTurn([
      _call('c1', 'config', {
        'op': 'set',
        'key': 'memory.projectPath',
        'value': mem2,
      }),
    ]);
  } else if (!results.contains('c2')) {
    events = toolTurn([
      _call('c2', 'config', {'op': 'check'}),
    ]);
  } else {
    events = toolTurn([
      _call('c3', 'memory_add', {'text': 'lives in the new store'}),
    ]);
  }
  final stream = AssistantMessageEventStream();
  for (final AssistantMessageEvent event in events) {
    stream.push(event);
  }
  return stream;
}

arguments.oldText:
// Content-addressed responder: every LM call inspects the conversation
// the CLI actually assembled and answers for THAT state (keyed on tool
// results, by call id). The sequential FakeStreamFunction consumed one
// scripted item per call IN ORDER, so a steering delivery — the CLI
// interrupts a mid-flight provider request and rebuilds it with the
// pending input — or a post-tool continuation consumed the WRONG next
// item and the scripted memory_add never ran: mem2 stayed absent and
// this assert flaked (CI run 43712787135; reproduced 0/6 locally on
// this head AND on origin/main — a pre-existing test-determinism gap,
// not a wrap regression). A rebuilt request re-asks for the same
// logical step and gets the same answer, so steering and continuations
// converge instead of skipping steps.
final served = <String>{};
AssistantMessageEventStream respondByState(
  Model model,
  Context context, {
  CancelToken? cancelToken,
}) {
  final results = context.messages
      .whereType<ToolResultMessage>()
      .map((m) => m.toolCallId)
      .toSet();
  // ignore: avoid_print
  print('=== RESPONDER call: results=$results roles='
      '${context.messages.map((m) => m.role).toSet()}');
  final List<AssistantMessageEvent> events;
  if (!results.contains('c1')) {
    events = toolTurn([
      _call('c1', 'config', {
        'op': 'set',
        'key': 'memory.projectPath',
        'value': mem2,
      }),
    ]);
  } else if (!results.contains('c2')) {
    events = toolTurn([
      _call('c2', 'config', {'op': 'check'}),
    ]);
  } else if (!results.contains('c3')) {
    events = toolTurn([
      _call('c3', 'memory_add', {'text': 'lives in the new store'}),
    ]);
  } else {
    final c3Result = context.messages
        .whereType<ToolResultMessage>()
        .firstWhere((m) => m.toolCallId == 'c3');
    // ignore: avoid_print
    print('=== c3 result isError=${c3Result.isError} '
        'text=${(c3Result.content.first as dynamic).text}');
    // ignore: avoid_print
    print('=== default store now: '
        '${Directory('\${project.path}/.fah/memory').listSync(recursive: true)}');
    events = textTurn('done');
  }
  for (final AssistantMessageEvent event in events) {
    if (event is ToolCallEndEvent) served.add(event.toolCall.id);
  }
  final stream = AssistantMessageEventStream();
  for (final AssistantMessageEvent event in events) {
    stream.push(event);
  }
  return stream;
}

